            <div className={`${styles.checkbox} ${styles[color.name]}`}>
              {color.isChecked && <CheckIcon className={styles.checkIcon} />}
            </div>
            <span className={styles.itemName}>{color.name}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

