.fruitItem {
  background:
    radial-gradient(circle at 80% 18%, rgba(240, 180, 41, 0.18), transparent 42%),
    var(--card);
  border: 1px solid var(--line);
  border-radius: 20px;
  aspect-ratio: 9 / 10;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  box-shadow: 0 10px 24px rgba(28, 42, 31, 0.05);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.fruitItem:hover {
  transform: translateY(-3px);
