}

.image {
  transform: translateY(-10px);
  height: var(--image-size);
  width: var(--image-size);
  object-fit: contain;
}

.info {
  position: absolute;
  bottom: var(--spacing);
  left: var(--spacing);
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: calc(100% - 70px);
}

.name,
.family,
.price {
  font-size: 15px;
}

