  font-family: var(--font-display);
  font-size: 20px;
}

.price {
  color: var(--leaf);
}

.express {
  position: absolute;
  top: var(--spacing);
  left: var(--spacing);
  z-index: 1;
}

.favorite,
.bag {
  width: var(--icon-size);
  height: var(--icon-size);
  cursor: pointer;
}

.favorite {
  position: absolute;
  top: var(--spacing);
  right: var(--spacing);
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.bag {
  position: absolute;
  bottom: var(--spacing);
  right: var(--spacing);
  transition: transform 0.2s ease;
}

