  display: flex;
  flex-direction: column;
}

.rightContainer {
  flex: 1;
  align-self: stretch;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.rightContainer h1 {
  font-size: clamp(36px, 5vw, 52px);
}

.info {
  display: flex;
  flex-direction: column;
}

.price {
  font-size: 22px;
  color: var(--leaf);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.unitHint {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-400);
}

.imageContainer {
  width: 460px;
  height: 460px;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 70% 20%, rgba(240, 180, 41, 0.22), transparent 48%),
    var(--card);
  border: 1px solid var(--line);
  border-radius: 28px;
}

.image {
  max-width: 160px;
  max-height: 160px;
}

.missing {
  max-width: 520px;
  margin: 80px auto;
  padding: 0 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  text-align: center;
}

.missing p {
  line-height: 1.5;
  color: var(--ink-soft);
  font-weight: 400;
}

.recommendations {
  padding: 0 50px;
}

.recommendationsTitle {
  font-size: 28px;
}

.recommendGrid {
  margin-top: 18px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.recommendGrid > a {
  display: block;
  min-width: 0;
}

.bone,
.imageBone {
  display: block;
  position: relative;
  overflow: hidden;
  background: var(--paper-deep);
}

.rightContainer .bone {
  height: 18px;
  width: min(100%, 280px);
  border-radius: 8px;
}

.rightContainer .bone:first-child {
  height: 44px;
  width: min(100%, 320px);
}

.titleBone {
  width: 220px;
  height: 32px;
  border-radius: 10px;
}

.cardBone {
  aspect-ratio: 9 / 10;
  border-radius: 20px;
}

.bone::after,
.imageBone::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255, 250, 242, 0.85), transparent);
  animation: fruitShimmer 1.4s ease infinite;
}

@keyframes fruitShimmer {
  100% {
    transform: translateX(100%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bone::after,
  .imageBone::after {
    animation: none;
  }
}

.categories {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.vitamin,
.color {
  white-space: nowrap;
  font-size: 10px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-200);
}

.color {
  border: none;
}

.checkoutButton,
.bagButton {
  max-width: 340px;
}

.fruitView {
  position: relative;
}

.buttonBack {
  position: absolute;
  top: 0px;
  left: 45px;
  margin-top: 16px;
}

.imageContainer {
  position: relative;
}

.favorite {
  position: absolute;
  top: 25px;
  right: 25px;
}

.favorite {
  height: 26px;
  width: 26px;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.imageContainer:hover .favorite {
  opacity: 1;
}

.favorite:hover {
  transform: scale(1.2);
}

.favorite.clicked {
  fill: var(--color-red);
  opacity: 1;
}

@media screen and (max-width: 940px) {
  .imageContainer {
    width: 360px;
    height: 360px;
  }
}

@media screen and (max-width: 835px) {
  .fruitView {
    flex-direction: column;
  }

  .leftContainer {
    flex: 1;
    align-self: stretch;
  }

  .imageContainer {
    width: auto;
    height: auto;
    aspect-ratio: 1/1;
  }

  .image {
    width: 28%;
    height: 28%;
  }

  .checkoutButton,
  .bagButton {
    max-width: none;
  }
}

@media screen and (max-width: 640px) {
  .recommendGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media screen and (max-width: 540px) {
  .fruitView {
    padding: 30px;
    padding-top: 76px;
  }

  .recommendations {
    padding: 0 30px;
  }

  .buttonBack {
    left: 22px;
  }
}

